-- B084: signed integer district Science; final floor occurs once in Lua.
SELECT 'SPC_CROSS_' || DistrictType,'REQUIREMENT_DISTRICT_TYPE_MATCHES' FROM Districts
WHERE DistrictType='DISTRICT_CAMPUS' OR DistrictType IN (SELECT CivUniqueDistrictType FROM DistrictReplaces WHERE ReplacesDistrictType='DISTRICT_CAMPUS');
SELECT 'SPC_CROSS_' || DistrictType,'DistrictType',DistrictType FROM Districts
WHERE DistrictType='DISTRICT_CAMPUS' OR DistrictType IN (SELECT CivUniqueDistrictType FROM DistrictReplaces WHERE ReplacesDistrictType='DISTRICT_CAMPUS');
SELECT 'SPC_CROSS_CAMPUS',RequirementId FROM Requirements WHERE RequirementId LIKE 'SPC_CROSS_DISTRICT_%';
